def fd_gradient(fun, x, eps=1e-6):
    eye = np.eye(len(x))
    return np.array([(fun(x+eps*d)-fun(x-eps*d))/(2*eps) for d in eye])

def fd_hessian(gradient, x, eps=1e-6):
    eye = np.eye(len(x))
    return np.column_stack([(gradient(x+eps*d)-gradient(x-eps*d))/(2*eps) for d in eye])

